{{ (() => { const m = qLotMetrics.data?.[0]; if (!m) return 'Search by lot ID, item, strain, status, or recipe, then select one result.'; const start = m.lifecycle_start_at ? moment(m.lifecycle_start_at).format('YYYY-MM-DD HH:mm') : 'Unknown'; const age = m.lifecycle_age_days != null ? Number(m.lifecycle_age_days).toFixed(1) + ' d' : '—'; const lr = qLineageForLot.data || []; const fmt = r => `${r.related_id || 'Unknown lot'}${r.related_item_name ? ' (' + r.related_item_name + ')' : ''}`; const grain = lr.filter(r => r.direction === 'upstream' && r.relationship_type === 'grain_input' && r.related_entity_type === 'lot').map(fmt).join(', ') || '—'; const substrate = lr.filter(r => r.direction === 'upstream' && r.relationship_type === 'substrate_input' && r.related_entity_type === 'lot').map(fmt).join(', ') || '—'; return `Stage: ${m.lifecycle_stage || m.status || 'Unknown'} · Status: ${m.status || 'Unknown'} · Lifecycle age: ${age}
