{{ (() => {
  const status = appsmith.store.reportingCohortStatus || "idle";
  if (status === "loading") return "Loading the applied cohort…";
  if (status === "error") return `Unable to load cohort analytics: ${appsmith.store.reportingCohortError || 'Unknown query error'}`;
