  const filters = appsmith.store.reportingCohortFilterSummary ? '\nApplied: ' + appsmith.store.reportingCohortFilterSummary : '';
  return `Cohort: ${n(r.cohort_lots)} lots · Contaminated: ${n(r.contaminated_lots)} (${pct(r.contamination_rate_pct)}) · Harvested: ${n(r.harvested_lots)} (${pct(r.harvest_rate_pct)})\nMedian cycle — Colonization: ${n(r.median_colonization_days)} d · Spawn → fruiting: ${n(r.median_spawn_to_fruiting_days)} d · Fruiting: ${n(r.median_fruiting_days)} d · Grain age at spawn: ${n(r.median_grain_age_days)} d\nHarvest — Total: ${n(r.total_harvest_g)} g · Average per harvested lot: ${n(r.avg_harvest_g_per_harvested_lot)} g · Quality-flagged lots: ${n(r.quality_flagged_lots)}${filters}`;
