actionConfiguration.body:
async function () {
  if (!LotsPage.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.")) return;
  const weightG = Number(inpHarvestWeightG.text);
  const flushNo = Number(inpHarvestFlushNo.text);
  const freshTrayCount = LotsHarvest.harvestFreshTrayCount();
  const frozenTrayCount = LotsHarvest.harvestFrozenTrayCount();
  const totalTrayCount = freshTrayCount + frozenTrayCount;
  const freshLocationId = selHarvestFreshStorageLocation.selectedOptionValue;
  const frozenLocationId = selHarvestFrozeStorageLocation.selectedOptionValue;
  const validFreshLocationIds = LotsHarvest.freshHarvestLocationOptions().map(o => String(o.value));
  const validFrozenLocationIds = LotsHarvest.frozenHarvestLocationOptions().map(o => String(o.value));
  if (!Number.isFinite(weightG) || weightG <= 0) {
    showAlert("Enter harvest weight in grams.", "warning");
    return;
  }
  if (!Number.isFinite(flushNo) || flushNo <= 0) {
    showAlert("Enter a valid flush number.", "warning");
    return;
  }
  if (totalTrayCount <= 0) {
    showAlert("Enter at least one fresh or freezer tray.", "warning");
    return;
  }
  if (freshTrayCount > 0 && (!freshLocationId || !validFreshLocationIds.includes(String(freshLocationId)))) {
    showAlert("Select a Fulfillment or product-ready destination for fresh harvest trays.", "warning");
    return;
  }
  if (frozenTrayCount > 0 && (!frozenLocationId || !validFrozenLocationIds.includes(String(frozenLocationId)))) {
    showAlert("Select a freezer/frozen destination for freezer tray harvest output.", "warning");
    return;
  }
  if (appsmith.store.harvest_submitting === true) return null;
  await storeValue("harvest_submitting", true);
  try {
    const res = await qHarvestLot.run();
    showAlert("Harvest created " + res[0].created_count + " tray product(s).", "success");
    closeModal(modalHarvestLot.name);
    await LotsPage.refresh();
    return res;
  } catch (e) {
    showAlert(e?.message || String(e), "error");
    return null;
  } finally {
    await storeValue("harvest_submitting", false);
  }
}

