actionConfiguration.body:
async function (row) {
  const original = LotsPage.lotsTableOriginalRow(row);
  const edited = {
    ...original,
    ...row || ({})
  };
  const newLocationId = edited?.location_id;
  const validation = LotsPage.lotsTableLocationEditValidation(edited, newLocationId);
  if (!validation.ok) {
    showAlert(validation.message, "warning");
    return null;
  }
  await storeValue("lots_table_move_lot_id", original.nocopk);
  await storeValue("lots_table_move_location_id", newLocationId);
  try {
    const res = await qLotsTableMoveLocation.run();
    const movedCount = res?.[0]?.moved_count ?? 0;
    showAlert(`Moved ${movedCount} lot(s).`, "success");
    await qLots.run();
    return res;
  } catch (e) {
    showAlert(e?.message || String(e), "error");
    await storeValue("lots_error", e?.message || String(e));
    return null;
  }
}

