actionConfiguration.body:
function () {
  const text = LotsSpawnToBulk.spawnToBulkBlockSizesText();
  if (!text) return [];
  return text.split(",").map(s => s.trim()).filter(Boolean).map(token => {
    if (token.includes(":")) {
      const [item_code, ratio] = token.split(":").map(x => x.trim());
      return {
        item_code,
        ratio: Number(ratio)
      };
    }
    return {
      ratio: Number(token)
    };
  }).filter(x => Number.isFinite(x.ratio) && x.ratio > 0);
}

