  const colonizing = opts.find(o => String(o.label || "").toLowerCase().includes("colon"));
  const incubation = opts.find(o => String(o.label || "").toLowerCase().includes("incubat"));
  return (darkRoom || colonizing || incubation || opts[0])?.value || "";
}

