async function () {
  txtErrLots.setText("");
  try {
    const requestedLot = String(appsmith.URL?.queryParams?.lot || "").trim();
    const validRequestedLot = !requestedLot || (/^(LOT)-[A-Za-z0-9-]+$/i).test(requestedLot);
    const previousSelection = String(inpStrains.selectedOptionValue || "All");
    const speciesRows = await qSpecies.run();
    const validSelections = new Set(["All", ...(speciesRows || []).map(row => String(row?.species_strain || "").trim()).filter(Boolean)]);
    if (!validSelections.has(previousSelection)) {
