function (row) {
  const category = LotsSpawnToBulk.normalizeCategory(row?.item_category_mat || row?.item_category);
  const status = LotsSpawnToBulk.normalizeStatus(row?.status);
  if (category !== "substrate") return false;
  if (LotsSpawnToBulk.lotIsTerminal(row)) return false;
  if (row?.spawned_at || row?.inoculated_at) return false;
  return !["spawned", "colonizing", "fullycolonized", "colonized", "fruiting", "frozen", "coldshock"].some(s => status.includes(s));
}

