actionConfiguration.body:
async function () {
  const filters = {
    dateBasis: selCohortDateBasis.selectedOptionValue || "lifecycle_start",
    startAt: dpStart.selectedDate || "",
    endAt: dpEnd.selectedDate || "",
    itemCategory: selCohortCategory.selectedOptionValue || "",
    itemName: selCohortItem.selectedOptionValue || "",
    strain: selSpecies.selectedOptionValue || "",
    grainItem: selGrain.selectedOptionValue || "",
    substrateItem: selSubstrate.selectedOptionValue || ""
  };
  const labels = [`Date basis: ${selCohortDateBasis.selectedOptionLabel || filters.dateBasis}`, `Range: ${dpStart.formattedDate || "Any"} → ${dpEnd.formattedDate || "Any"}`, filters.itemCategory ? `Category: ${filters.itemCategory}` : "", filters.itemName ? `Item: ${filters.itemName}` : "", filters.strain ? `Strain: ${filters.strain}` : "", filters.grainItem ? `Grain: ${filters.grainItem}` : "", filters.substrateItem ? `Substrate: ${filters.substrateItem}` : ""].filter(Boolean);
  await storeValue("reportingCohortFilters", filters);
  await storeValue("reportingCohortFilterSummary", labels.join(" · "));
  await storeValue("reportingCohortStatus", "loading");
  await storeValue("reportingCohortError", "");
  const jobs = [["summary", qContamIncidencePerItem.run()], ["distributions", qCohortCycleTimes.run()], ["monthly yield", qMonthlyHarvestYield.run()], ["monthly contamination", qContamIncidenceMonthly.run()], ["cohort lots", qCohortOutliers.run()]];
  const settled = await Promise.allSettled(jobs.map(j => j[1]));
  const failures = settled.map((result, index) => {
    if (result.status === "fulfilled") return "";
    const reason = result.reason?.message || String(result.reason || "unknown error");
    return `${jobs[index][0]}: ${reason}`;
  }).filter(Boolean);
  if (failures.length) {
    const message = failures.join(";  ");
    await storeValue("reportingCohortStatus", "error");
    await storeValue("reportingCohortError", message);
    showAlert("Cohort analytics failed: " + message, "error");
    return false;
  }
  await storeValue("reportingCohortStatus", "ready");
  return true;
}

