function (row) {
  const trayStates = String(row?.tray_state || "").toLowerCase().split(/[,;|]+/).map(s => s.trim()).filter(Boolean);
  const location = String(row?.storage_location || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  const inactiveStates = ["empty_tray", "empty tray", "compost", "composted", "spoiled", "retired", "expired", "consumed", "shipped"];
  const inactiveLocations = ["compost", "consumed", "expired", "retired", "shipped"];
  return !trayStates.some(s => inactiveStates.includes(s)) && !inactiveLocations.includes(location);
}

