        showAlert(`Product not found on Products page: ${requestedProduct}`, "warning");
        return;
      }
      await resetWidget("tblProducts", true);
      await tblProducts.setSelectedRowIndices([requestedIndex]);
      if (String(appsmith.URL?.queryParams?.source || "").toLowerCase() === "qr") {
        showAlert(`Loaded ${rows[requestedIndex].product_id} from QR scan.`, "success");
      }
    }
  } catch (e) {
    showAlert(e?.message || String(e), "error");
  }
}

