function () {
  const invalidNameParts = ["shipped", "shipping", "expired", "compost", "consumed", "retired", "fulfillment", "products storage", "product storage", "product-ready", "product ready", "lab", "dark room"];
  return (qProductLocations.data || []).filter(l => {
    const name = String(l.name || "").trim();
    const lower = name.toLowerCase();
    if (!name) return false;
    if (l.active === false) return false;
    if (invalidNameParts.some(part => lower.includes(part))) return false;
    return lower.includes("freezer") || lower.includes("frozen") || lower.includes("freeze");
  }).map(l => ({
    label: l.name,
    value: l.nocopk
  }));
}

