async function () {
  const validation = LotsDrawSyringes.lotModalValidation("draw_syringes");
  if (!validation.ok) {
    showAlert(validation.message || "Select exactly one active LC flask lot first.", "warning");
    return;
  }
  const count = Number(inpSyringeCount.text);
  const mlEach = Number(inpSyringeMlEach.text);
  const mode = selDrawSyringeOutputType.selectedOptionValue || "product";
  const location = selDrawSyringeLocation.selectedOptionValue;
  const validLocationIds = LotsDrawSyringes.drawSyringeLocationOptions().map(o => String(o.value));
  if (!Number.isFinite(count) || count <= 0) {
    showAlert("Enter a syringe count greater than 0.", "warning");
    return;
  }
  if (!Number.isFinite(mlEach) || mlEach <= 0) {
    showAlert("Enter mL per syringe greater than 0.", "warning");
    return;
  }
  const requestedMl = count * mlEach;
  const remainingMl = LotsDrawSyringes.selectedFlaskRemainingMl();
  if (!Number.isFinite(remainingMl) || remainingMl <= 0) {
    showAlert("Selected LC flask has no remaining volume.", "warning");
    return;
  }
  if (requestedMl > remainingMl) {
    showAlert(`Not enough LC volume. Need ${requestedMl} ml, have ${remainingMl} ml.`, "warning");
    return;
  }
  if (!location || !validLocationIds.includes(String(location))) {
    showAlert("Select a refrigerated Storage Location for drawn syringes.", "warning");
    return;
  }
  try {
    const res = mode === "product" ? await qDrawSyringeProducts.run() : await qDrawSyringes.run();
    showAlert(mode === "product" ? "Syringe products created." : "Syringe lots created.", "success");
    await Promise.allSettled([resetWidget("inpSyringeCount", true), resetWidget("inpSyringeMlEach", true), resetWidget("inpDrawSyringesNotes", true), resetWidget("selDrawSyringeOutputType", true), resetWidget("inpStrains", true), resetWidget("chkRegulated", true), resetWidget("chkUnRegulated", true)]);
    await LotsDrawSyringes.refresh();
    await Promise.allSettled([resetWidget("tblLots", true), resetWidget("selSyringeItem", true), resetWidget("selDrawSyringeLocation", true)]);
    return res;
  } catch (e) {
    showAlert(e?.message || String(e), "error");
    return null;
  }
}

