async function () {
  if (!InventoryReconcile.canFinalize()) {
    showAlert("Review the reconciliation confirmation requirements before finalizing.", "warning");
    return;
  }
  if (appsmith.store.recon_submitting === true) return;
  await storeValue("recon_submitting", true);
  const expectedRows = appsmith.store.recon_expected_rows || [];
  const foundRows = appsmith.store.recon_found_rows || [];
  const idsFor = (rows, type) => rows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === type).map(row => Number(row.nocopk)).filter(Number.isFinite);
  try {
    const rows = await qReconFinalize.run({
      location_id: Number(appsmith.store.recon_location_id),
      expected_product_ids: idsFor(expectedRows, "product"),
      found_product_ids: idsFor(foundRows, "product"),
      expected_lot_ids: idsFor(expectedRows, "lot"),
      found_lot_ids: idsFor(foundRows, "lot"),
      allow_shipped_correction: chkReconCorrectShipped.isChecked === true,
      operator: InventoryReconcile.currentOperator(),
      notes: String(inpReconNotes.text || "").trim()
    });
    const result = (rows || [])[0] || ({});
    const message = [`Reconciliation complete for ${result.target_location || appsmith.store.recon_location_name || "selected location"}.`, `${Number(result.moved_in_count || 0)} moved/restored into location,`, `${Number(result.marked_missing_count || 0)} moved to Missing or Lost,`, `${Number(result.skipped_expected_count || 0)} skipped because their state changed after the snapshot.`, `Processed ${Number(result.expected_product_count || 0)} expected products and ${Number(result.expected_lot_count || 0)} expected lots.`].join(" ");
    await storeValue("recon_last_result", result);
    await storeValue("recon_last_message", message);
    closeModal(modalReconFinalize.name);
    await storeValue("recon_active", false);
    await storeValue("recon_location_id", "");
    await storeValue("recon_location_name", "");
    await storeValue("recon_started_at", "");
    await storeValue("recon_expected_rows", []);
    await storeValue("recon_found_rows", []);
    await inpReconProductNumber.setValue("");
    await inpReconNotes.setValue("");
    await resetWidget("chkReconCorrectShipped", true);
    await resetWidget("chkReconConfirmMissing", true);
    await resetWidget("tblReconExpectedProducts", true);
    await resetWidget("tblReconFoundProducts", true);
    await selReconLocation.setSelectedOption("");
    showAlert(message, Number(result.skipped_expected_count || 0) > 0 ? "warning" : "success");
  } catch (e) {
    showAlert(`Reconciliation failed; no partial Product or Lot changes were committed: ${e?.message || String(e)}`, "error");
  } finally {
    await storeValue("recon_submitting", false);
  }
}

