actionConfiguration.body:
async function (rawValue, fromScan) {
  const scanned = fromScan === true;
  if (!InventoryReconcile.isSessionActive()) {
    showAlert(scanned ? "Start a reconciliation before scanning inventory." : "Start a reconciliation before adding inventory.", "warning");
    return;
  }
  const inputValue = scanned ? rawValue : inpReconProductNumber.text;
  const inventoryNumber = InventoryReconcile.normalizeProductNumber(inputValue);
  if (!inventoryNumber) {
    showAlert(scanned ? "No Product or Lot identifier was detected in the scanned code." : "Enter a Product or Lot number.", "warning");
    return;
  }
  if (scanned && !(/^(?:PROD|LOT)-[A-Za-z0-9-]+$/i).test(inventoryNumber)) {
    showAlert("Scanned code does not contain a valid Product or Lot identifier.", "warning");
    return;
  }
  const scanKey = inventoryNumber.toLowerCase();
  const now = Date.now();
  if (scanned) {
    const lastKey = String(appsmith.store.recon_last_scan_id || "");
    const lastAt = Number(appsmith.store.recon_last_scan_at || 0);
    const processingAt = Number(appsmith.store.recon_scan_processing_at || 0);
    const processing = appsmith.store.recon_scan_processing === true && now - processingAt < 5000;
    if (processing || lastKey === scanKey && now - lastAt < 2000) return;
    await storeValue("recon_scan_processing", true);
    await storeValue("recon_scan_processing_at", now);
    await storeValue("recon_last_scan_id", scanKey);
    await storeValue("recon_last_scan_at", now);
  }
  try {
    if (scanned) await inpReconProductNumber.setValue(inventoryNumber);
    const existing = (appsmith.store.recon_found_rows || []).find(row => String(row.inventory_id || row.product_id || row.lot_id || "").toLowerCase() === inventoryNumber.toLowerCase());
    if (existing) {
      await inpReconProductNumber.setValue("");
      showAlert(`${existing.inventory_type || "Inventory"} ${existing.inventory_id || inventoryNumber} is already in the physically found list.`, "info");
      return;
    }
    const rows = await qReconFindProduct.run({
      product_code: inventoryNumber
    });
    if ((rows || []).length > 1) {
      showAlert(`More than one inventory record matched ${inventoryNumber}; resolve the duplicate identifier before reconciling it.`, "error");
      return;
    }
    const row = (rows || [])[0];
    if (!row) {
      showAlert(`Product or Lot not found: ${inventoryNumber}`, "error");
      return;
    }
    const foundRows = [...appsmith.store.recon_found_rows || [], row];
    await storeValue("recon_found_rows", foundRows);
    await inpReconProductNumber.setValue("");
    await resetWidget("tblReconExpectedProducts", true);
    await resetWidget("tblReconFoundProducts", true);
    const action = InventoryReconcile.actionForFoundRow(row);
    const displayId = row.inventory_id || row.product_id || row.lot_id || row.nocopk;
    if (String(action).startsWith("BLOCKED:")) {
      showAlert(`${row.inventory_type || "Inventory"} ${displayId}: ${action}`, "warning");
    } else if (String(action).startsWith("REVIEW:")) {
      showAlert(`${row.inventory_type || "Product"} ${displayId}: ${action}. Shipped correction and notes are required before finalizing.`, "warning");
    } else if (scanned) {
      showAlert(`${row.inventory_type || "Inventory"} ${displayId} scanned and added as physically found.`, "success");
    }
  } catch (e) {
    showAlert(`Unable to look up ${inventoryNumber}: ${e?.message || String(e)}`, "error");
  } finally {
    if (scanned) {
      await storeValue("recon_scan_processing", false);
      await storeValue("recon_scan_processing_at", 0);
    }
  }
}

