async function () {
  if (!InventoryReconcile.isSessionActive()) return;
  const selected = tblReconExpectedProducts.selectedRows || [];
  if (!selected.length) {
    showAlert("Select one or more expected inventory records first.", "warning");
    return;
  }
  const found = [...appsmith.store.recon_found_rows || []];
  const foundKeys = new Set(found.map(row => String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`)));
  let added = 0;
  selected.forEach(row => {
    const key = String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`);
    if (!foundKeys.has(key)) {
      const cleanRow = {
        ...row
      };
      delete cleanRow.reconciliation_status;
      found.push(cleanRow);
      foundKeys.add(key);
      added += 1;
    }
  });
  await storeValue("recon_found_rows", found);
  await resetWidget("tblReconExpectedProducts", true);
  await resetWidget("tblReconFoundProducts", true);
  showAlert(`${added} inventory record${added === 1 ? "" : "s"} marked physically found.`, "success");
}

