function () {
  if (!InventoryReconcile.isSessionActive()) {
    return appsmith.store.recon_last_message || "Select a physical storage location, then start a reconciliation. Products and Lots are counted together. No database changes occur until Finalize.";
  }
  const started = appsmith.store.recon_started_at ? new Date(appsmith.store.recon_started_at).toLocaleString() : "unknown time";
  const rows = appsmith.store.recon_expected_rows || [];
  const products = rows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "product").length;
  const lots = rows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "lot").length;
  return `Reconciling ${appsmith.store.recon_location_name || "selected location"} • started ${started} • ${rows.length} expected at start (${products} product${products === 1 ? "" : "s"}, ${lots} lot${lots === 1 ? "" : "s"}).`;
}

