  const foundRows = appsmith.store.recon_found_rows || [];
  const expectedProducts = expectedRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "product").length;
  const expectedLots = expectedRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "lot").length;
  const foundProducts = foundRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "product").length;
  const foundLots = foundRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "lot").length;
  const missing = InventoryReconcile.missingRows().length;
  const plannedMissing = InventoryReconcile.changeRows().filter(row => row.action === "Move to Missing or Lost").length;
  const skippedTerminal = InventoryReconcile.changeRows().filter(row => String(row.action || "").startsWith("SKIP:")).length;
  const alreadyCorrect = InventoryReconcile.foundRows().filter(row => row.action === "Already correct").length;
  const shipped = InventoryReconcile.shippedFoundRows().length;
  const blocked = InventoryReconcile.blockedFoundRows().length;
  const movingIn = InventoryReconcile.foundRows().filter(row => row.action !== "Already correct" && !String(row.action || "").startsWith("BLOCKED:")).length;
  return `Expected: ${expectedRows.length} (${expectedProducts} products / ${expectedLots} lots) | Physically found: ${foundRows.length} (${foundProducts} products / ${foundLots} lots) | Not found: ${missing} | Planned Missing: ${plannedMissing} | Terminal skips: ${skippedTerminal} | Already correct: ${alreadyCorrect} | Move/restore in: ${movingIn} | Shipped product review: ${shipped} | Blocked: ${blocked}`;
}

