function () {
  const term = RecipeAdmin.normalize(inpIngredientSearch.text);
  const status = String(selIngredientActiveFilter.selectedOptionValue || "all");
  return (qRecipeAdminIngredients.data || []).filter(i => {
    if (status === "active" && !i.active) return false;
    if (status === "inactive" && i.active) return false;
    if (!term) return true;
    return [i.ingredient_id, i.name, i.category, i.default_unit, i.preferred_vendor, i.notes].some(v => RecipeAdmin.normalize(v).includes(term));
  });
}

