actionConfiguration.body:
function () {
  const term = RecipeAdmin.normalize(inpRecipeSearch.text);
  const status = String(selRecipeActiveFilter.selectedOptionValue || "all");
  return (qRecipeAdminRecipes.data || []).filter(r => {
    if (status === "active" && !r.active) return false;
    if (status === "inactive" && r.active) return false;
    if (!term) return true;
    return [r.recipe_id, r.name, r.category, r.description, r.batch_yield_text, r.ingredients, r.notes].some(v => RecipeAdmin.normalize(v).includes(term));
  });
}

