actionConfiguration.body:
async function () {
  const item = RecipeAdmin.currentPlanItem();
  const recipePk = Number(selRecipePlanRecipe.selectedOptionValue || 0);
  const role = String(selRecipePlanComponentRole.selectedOptionValue || "").trim();
  if (!item?.nocopk || !recipePk || !role) {
    showAlert("Item, Recipe, and Component Role are required.", "warning");
    return;
  }
  const mode = String(item.component_mode || "none").toLowerCase();
  if (!["single_recipe", "multi_recipe"].includes(mode)) {
    showAlert("The selected Item does not use Recipe Components.", "warning");
    return;
  }
  if (mode === "multi_recipe" && !String(inpRecipePlanComponentSet.text || "").trim()) {
    showAlert("Component Set is required for multi-recipe Items.", "warning");
    return;
  }
  const optNum = value => String(value ?? "").trim() === "" ? null : Number(value);
  try {
    await qRecipeAdminSaveItemComponent.run({
      nocopk: Number(appsmith.store.recipe_admin_item_component_nocopk || 0) || null,
      item_id: Number(item.nocopk),
      component_set: String(inpRecipePlanComponentSet.text || "").trim(),
      recipe_id: recipePk,
      component_role: role,
      unit_size_lb: optNum(inpRecipePlanUnitSizeLb.text),
      default_weight_lb: optNum(inpRecipePlanDefaultWeightLb.text),
      default_percent: optNum(inpRecipePlanDefaultPercent.text),
      sort_order: optNum(inpRecipePlanSortOrder.text),
      active: chkRecipePlanComponentActive.isChecked === true,
      notes: String(txtRecipePlanComponentNotes.text || "").trim()
    });
    await qRecipeAdminItemComponents.run({
      item_id: Number(item.nocopk)
    });
    await RecipeAdmin.newItemComponent();
    showAlert("Item Recipe Component saved.", "success");
  } catch (e) {
    showAlert(`Unable to save Item Recipe Component: ${e?.message || String(e)}`, "error");
  }
}

