actionConfiguration.body:
async function () {
  const recipePk = Number(appsmith.store.recipe_admin_recipe_nocopk || 0);
  const section = String(selRecipeStepSection.selectedOptionValue || "").trim();
  const instruction = String(txtRecipeStepInstruction.text || "").trim();
  const optNum = value => String(value ?? "").trim() === "" ? null : Number(value);
  const sectionOrder = optNum(inpRecipeStepSectionOrder.text);
  const stepOrder = optNum(inpRecipeStepOrder.text);
  if (!recipePk || !section || !instruction) {
    showAlert("Recipe, Section, and Instruction are required.", "warning");
    return;
  }
  if (sectionOrder !== null && !Number.isFinite(sectionOrder) || stepOrder !== null && !Number.isFinite(stepOrder)) {
    showAlert("Section Order and Step Order must be numeric when supplied.", "warning");
    return;
  }
  try {
    await qRecipeAdminSaveRecipeStep.run({
      nocopk: Number(appsmith.store.recipe_admin_recipe_step_nocopk || 0) || null,
      recipe_id: recipePk,
      section,
      section_order: sectionOrder,
      step_order: stepOrder,
      instruction,
      active: chkRecipeStepActive.isChecked === true,
      notes: String(txtRecipeStepNotes.text || "").trim()
    });
    await qRecipeAdminRecipeSteps.run({
      recipe_id: recipePk
    });
    await RecipeAdmin.newRecipeStep();
    showAlert("Recipe instruction step saved.", "success");
  } catch (e) {
    showAlert(`Unable to save Recipe instruction step: ${e?.message || String(e)}`, "error");
  }
}

