    margin: 0 0 0.12in;
    color: #111827;
    font-size: 24pt;
    line-height: 1.12;
    font-weight: 700;
  }
  h2 {
    margin: 0.30in 0 0.10in;
    padding-bottom: 0.04in;
    border-bottom: 1px solid #d1d5db;
    color: #1f2937;
    font-size: 14.5pt;
    line-height: 1.2;
    page-break-after: avoid;
    break-after: avoid;
  }
  p { margin: 0 0 0.10in; }
  p.recipe-id { margin-top: -0.02in; color: #6b7280; font-size: 9.5pt; }
  .status {
    margin: 0.10in 0;
    padding: 0.07in 0.10in;
    border-left: 3px solid #b45309;
    background: #fffbeb;
    color: #78350f;
  }
  .bullet {
    display: flex;
    gap: 0.08in;
    margin: 0 0 0.075in;
    page-break-inside: avoid;
    break-inside: avoid;
