export default {
  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();
    if (email) return email;
    if (name) return name;
    return "system";
  },

	async init() {
		await storeValue("ster_in_error", "");
		await storeValue("ster_in_submitting", false);
		await storeValue("ster_in_last_success_signature", "");
		await storeValue("ster_in_last_created_run_id", "");

		await qItems.run();
		const options = await qRecipes.run();
		const optionValues = (options || []).map(option => String(option.option_value));
		const storedSelection = String(appsmith.store.ster_in_selected_recipe || "");

		if (storedSelection && optionValues.includes(storedSelection)) {
			await selPlannedRecipe.setSelectedOption(storedSelection);
		} else if (storedSelection) {
			await storeValue("ster_in_selected_recipe", "");
		}
	},

	validate({ show = true } = {}) {
		const errs = [];

		if (!selProcessType.selectedOptionValue) {
			errs.push("Select a process type.");
		}

		if (!selPlannedItem.selectedOptionValue) {
			errs.push("Select a planned item.");
		}

		const selectedItem = (qItems.data || []).find(
			i => String(i.nocopk) === String(selPlannedItem.selectedOptionValue)
		);
		const componentMode = String(selectedItem?.component_mode || "single_recipe").trim().toLowerCase();

		if (!selPlannedRecipe.selectedOptionValue) {
			errs.push(componentMode === "multi_recipe"
				? "Select a component set for this multi-recipe item."
				: "Select a planned recipe for this single-recipe item.");
		}

		const unit = Number(inpPlannedUnitSize.text);
		const cnt = Number(inpPlannedCount.text);

		if (!Number.isFinite(unit) || unit <= 0) {
			errs.push("Planned unit size must be > 0.");
		}

		if (!Number.isFinite(cnt) || cnt <= 0) {
			errs.push("Planned count must be > 0.");
		}

		if (show) {
			errs.forEach(msg => showAlert(msg, "error"));
		}

		return errs;
	},

  sql: {
    str(v) {
      if (v === undefined || v === null) return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    ts(d) {
      if (!d) return "NULL";
      const parsed = new Date(d);
      if (Number.isNaN(parsed.getTime())) return "NULL";
      const s = parsed.toISOString().slice(0, 19).replace("T", " ");
      return "'" + s + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
  },

	formSignature() {
		const selectedItem = (qItems.data || []).find(
			i => String(i.nocopk) === String(selPlannedItem.selectedOptionValue)
		);
		const componentMode = String(selectedItem?.component_mode || "single_recipe").trim().toLowerCase();

		return JSON.stringify({
			planned_item_id: selPlannedItem.selectedOptionValue || "",
			planned_recipe_id: componentMode === "multi_recipe" ? "" : (selPlannedRecipe.selectedOptionValue || ""),
			planned_component_set: componentMode === "multi_recipe" ? (selPlannedRecipe.selectedOptionValue || "") : "",
			component_mode: componentMode,
			process_type: selProcessType.selectedOptionValue || "",
			planned_count: String(inpPlannedCount.text || "").trim(),
			planned_unit_size: String(inpPlannedUnitSize.text || "").trim(),
			notes: String(inpRunNotes.text || "").trim(),
			start_time: dpStartTime.formattedDate || ""
		});
	},

	isSubmitting() {
		return appsmith.store.ster_in_submitting === true;
	},

	isDuplicateOfLastSuccess() {
		const current = this.formSignature();
		return !!current && current === appsmith.store.ster_in_last_success_signature;
	},

	async markFormChanged() {
		await storeValue("ster_in_last_success_signature", "");
		await storeValue("ster_in_error", "");
	},

	async resetCreateRunForm() {
		await selPlannedItem.setSelectedOption("");
		await selPlannedRecipe.setSelectedOption("");
		await selProcessType.setSelectedOption("sterilize");
		await inpPlannedCount.setValue("");
		await inpPlannedUnitSize.setValue("");
		await inpRunNotes.setValue("");
		await dpStartTime.setValue(new Date());
		await storeValue("ster_in_default_size", "");
		await storeValue("ster_in_selected_item", "");
		await storeValue("ster_in_selected_recipe", "");
		await storeValue("ster_in_unit_size", "");
	},

	async createRun() {
		if (this.isSubmitting()) {
			return;
		}

		await storeValue("ster_in_submitting", true);
		await storeValue("ster_in_error", "");

		try {
			const errs = this.validate({ show: true });
			if (errs.length) {
				await storeValue("ster_in_error", errs.join(" "));
				return;
			}

			const signature = this.formSignature();

			if (signature === appsmith.store.ster_in_last_success_signature) {
				showAlert(
					"This run was already created. Change the inputs before creating another run.",
					"warning"
				);
				return;
			}

			await qCreateRun.run();
			const createdRow = (qCreateRun.data || [])[0] || {};
			const runId = String(createdRow.steri_run_id || "").trim();
			const msg = runId
				? "Successfully created sterilizer run " + runId
				: "Successfully created sterilizer run.";

			await storeValue("ster_in_last_success_signature", signature);
			await storeValue("ster_in_last_created_run_id", runId);
			await storeValue("ster_in_error", msg);

			showAlert(msg, "success");

			await this.resetCreateRunForm();

			await Promise.allSettled([
				qItems.run(),
				qRecipes.run()
			]);
		} catch (e) {
			const msg = e && e.message ? e.message : String(e);
			showAlert("Error creating run: " + msg, "error");
			await storeValue("ster_in_error", msg);
		} finally {
			await storeValue("ster_in_submitting", false);
		}
	},

	async setSelectedItemSize({ resetSize = true } = {}) {
    const selectedValue = selPlannedItem.selectedOptionValue;
    const selectedItem = (qItems.data || []).find(
      item => String(item.nocopk) === String(selectedValue)
    );
    const componentMode = String(selectedItem?.component_mode || "single_recipe").trim().toLowerCase();
    const previousSelection = String(
      selPlannedRecipe.selectedOptionValue
      || appsmith.store.ster_in_selected_recipe
      || ""
    );

    await storeValue("ster_in_selected_item", selectedValue || "");

    if (resetSize) {
      await selPlannedRecipe.setSelectedOption("");
      await storeValue("ster_in_selected_recipe", "");
      const defaultSize = selectedItem
        ? (selectedItem.default_unit_size_lb ||
          selectedItem.default_unit_size_ml ||
          selectedItem.default_unit_size_g ||
          selectedItem.default_unit_size_oz ||
          "")
        : "";
      const defaultSizeText = defaultSize === "" ? "" : String(defaultSize);
      await storeValue("ster_in_default_size", defaultSize);
      await storeValue("ster_in_unit_size", defaultSizeText);
      await inpPlannedUnitSize.setValue(defaultSizeText);
    } else {
      await storeValue(
        "ster_in_unit_size",
        String(inpPlannedUnitSize.text || "").trim()
      );
    }

    if (!resetSize && componentMode !== "multi_recipe") {
      return;
    }

    const options = await qRecipes.run();
    const optionValues = (options || []).map(option => String(option.option_value));

    if (!resetSize && previousSelection && optionValues.includes(previousSelection)) {
      await selPlannedRecipe.setSelectedOption(previousSelection);
      await storeValue("ster_in_selected_recipe", previousSelection);
      return;
    }

    if (componentMode === "multi_recipe" && optionValues.length === 1) {
      await selPlannedRecipe.setSelectedOption(optionValues[0]);
      await storeValue("ster_in_selected_recipe", optionValues[0]);
    } else if (!resetSize && previousSelection) {
      await selPlannedRecipe.setSelectedOption("");
      await storeValue("ster_in_selected_recipe", "");
    }
  },

  async refresh() {
    await this.init();
  },
};

