unpublishedCollection.body:
export default {
	currentOperator() {
		const email = (appsmith.user?.email || "").trim().toLowerCase();
		const name = (appsmith.user?.name || "").trim();
		if (email) return email;
		if (name) return name;
		return "system";
	},

	sql: {
		str(v) {
		if (v === undefined || v === null || v === "") return "NULL";
		return "'" + String(v).replace(/'/g, "''") + "'";
		},
		num(v) {
		const n = Number(v);
		return Number.isFinite(n) ? String(n) : "NULL";
		},
		arrStr(arr) {
		// Safe Postgres text[] expression for use with = ANY(...)
		if (!arr || arr.length === 0) return "ARRAY[]::text[]";
		const vals = arr.map(x => "'" + String(x).replace(/'/g, "''") + "'");
		return "ARRAY[" + vals.join(", ") + "]::text[]";
		},
		arrBigint(arr) {
		// Safe Postgres bigint[] expression for function args
		if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
		const vals = arr.map(x => {
			const n = Number(x);
			return Number.isFinite(n) ? String(n) : "NULL";
		}).filter(x => x !== "NULL");
		if (vals.length === 0) return "ARRAY[]::bigint[]";
		return "ARRAY[" + vals.join(", ") + "]::bigint[]";
		},
	},

	sqlNull() {
		return "NULL";
	},

	sqlNumOrNull(v) {
		return this.sql.num(v);
	},

	sqlTimestampOrNull(v) {
		if (v === null || v === undefined || v === "" || v === "NULL") return "NULL";
		return this.sql.str(v);
	},

	selectedLotIds() {
		return this.selectedLotRows()
			.map(r => Number(r.nocopk))
			.filter(Number.isFinite);
	},

	selectedLotIdsSql() {
		return this.selectedLotIds()
			.map(id => Number(id))
			.filter(Number.isFinite)
			.join(",");
	},

	formatSelectedLots() {
		const rows = (tblLots.selectedRows || []);
		if (!rows.length) return "(No lots selected)";
		return rows.map(r => {
		const lotId = r.lot_id ?? r.nocopk;
		const inoc = r.inoculated_at ? moment(r.inoculated_at).format("YYYY-MM-DD") : "";
		const item = r.item_name_mat || "";
		const strain = r.strain_species_strain_mat || "";
		return `${lotId} | inoc:${inoc} | ${item} | ${strain}`.trim();
		}).join("\n");
	},

	lotsTableOriginalRow(row) {
		const id = row?.nocopk;
		return (qLots.data || []).find(r => String(r.nocopk) === String(id)) || row || {};
	},

	locationById(locationId) {
		return (qLocations.data || []).find(l => String(l.nocopk) === String(locationId)) || null;
	},

	locationNameById(locationId) {
		const loc = this.locationById(locationId);
		return String(loc?.name || "").trim();
	},

	lotsTableLocationGroupFromName(name) {
		const lower = String(name || "").trim().toLowerCase();

		if (!lower) return "unknown";

		if (
			lower.includes("consumed") ||
			lower.includes("retired") ||
			lower.includes("compost") ||
			lower.includes("expired") ||
			lower.includes("contaminated") ||
			lower.includes("invalid") ||
			lower.includes("inviable")
		) {
			return "terminal";
		}

		if (lower.includes("freeze dryer") || lower.includes("freeze-dryer")) {
			return "freeze_dryer";
		}

		if (lower.includes("freezer")) {
			return "freezer";
		}

		if (lower.includes("fridge") || lower.includes("refrigerat")) {
			return "fridge";
		}

		if (lower.includes("fruiting")) {
			return "fruiting";
		}

		if (lower.includes("dark room")) {
			return "dark_room";
		}

		if (
			lower.includes("products storage") ||
			lower.includes("product storage") ||
			lower.includes("fulfillment") ||
			lower.includes("shipping") ||
			lower.includes("retail") ||
			lower.includes("market")
		) {
			return "product_storage";
		}

		if (
			lower.includes("new") ||
			lower.includes("receiving") ||
			lower.includes("intake") ||
			lower.includes("staging")
		) {
			return "new_lot";
		}

		if (lower.includes("lab")) {
			return "lab";
		}

		return "other";
	},

	lotsTableLocationEditValidation(row, proposedLocationId) {
		const original = this.lotsTableOriginalRow(row);
		const lotId = original?.nocopk;
		const lotLabel = original?.lot_id || lotId || "Selected lot";
		const status = String(original?.status || "").trim().toLowerCase();

		const fromLocationId = original?.location_id;
		const toLocationId = proposedLocationId ?? row?.location_id;

		const fromName = this.locationNameById(fromLocationId);
		const toName = this.locationNameById(toLocationId);

		const fromGroup = this.lotsTableLocationGroupFromName(fromName);
		const toGroup = this.lotsTableLocationGroupFromName(toName);

		if (!lotId) {
			return {
				ok: false,
				message: "Could not identify the lot being edited."
			};
		}

		if (!toLocationId || !toName) {
			return {
				ok: false,
				message: "Select a valid destination location."
			};
		}

		if (String(fromLocationId) === String(toLocationId)) {
			return {
				ok: true,
				message: ""
			};
		}

		if (
			status.includes("retired") ||
			status.includes("expired") ||
			status.includes("consumed") ||
			status.includes("compost")
		) {
			return {
				ok: false,
				message: `${lotLabel} is terminal/retired and should not be moved from the Lots table.`
			};
		}

		if (toGroup === "terminal") {
			return {
				ok: false,
				message: `${toName} is a terminal location. Use the Retire/Terminal workflow instead.`
			};
		}

		if (fromGroup === "freeze_dryer" || toGroup === "freeze_dryer") {
			return {
				ok: false,
				message: "Freeze Dryer movement should be handled from Products / freeze-dry workflow, not Lots table inline edit."
			};
		}

		if (status === "new" && toGroup !== "new_lot") {
			return {
				ok: false,
				message: "Moving New lots into production or product storage is a workflow action. Use the appropriate process modal instead."
			};
		}

		const sameClassAllowedGroups = [
			"product_storage",
			"fridge",
			"freezer",
			"fruiting",
			"new_lot",
			"lab",
			"dark_room"
		];

		if (
			fromGroup === toGroup &&
			sameClassAllowedGroups.includes(fromGroup)
		) {
			return {
				ok: true,
				message: ""
			};
		}

		if (fromGroup === "dark_room" && ["fridge", "freezer", "fruiting"].includes(toGroup)) {
			return {
				ok: false,
				message: "Moving from Dark Room to Fridge/Freezer/Fruiting is a transition. Use the Transition/Move modal."
			};
		}

		if (toGroup === "product_storage") {
			return {
				ok: false,
				message: "Moving lots into product storage is productizing/package behavior. Use Package Lots."
			};
		}

		return {
			ok: false,
			message: `Inline location edit only supports same-class moves. Use the appropriate workflow to move from ${fromName || "unknown"} to ${toName}.`
		};
	},

	lotsTableLocationOptionsForRow(row) {
		const original = this.lotsTableOriginalRow(row);

		return (qLocations.data || [])
			.filter(loc => {
				if (!loc?.nocopk || !loc?.name) return false;
				if (loc.active === false) return false;

				return this.lotsTableLocationEditValidation(original, loc.nocopk).ok;
			})
			.map(loc => ({
				label: loc.name,
				value: loc.nocopk
			}));
	},

	canSaveLotsTableLocationEdit(row) {
		const original = this.lotsTableOriginalRow(row);
		const newLocationId = row?.location_id;

		if (!original?.nocopk) return false;
		if (!newLocationId) return false;

		if (String(original.location_id) === String(newLocationId)) {
			return false;
		}

		return this.lotsTableLocationEditValidation(row, newLocationId).ok;
	},

	async onLotsTableLocationChanged(row) {
		const validation = this.lotsTableLocationEditValidation(row, row?.location_id);

		if (!validation.ok) {
			showAlert(validation.message, "warning");
			return false;
		}

		return true;
	},

	async saveLotsTableLocationEdit(row) {
		const original = this.lotsTableOriginalRow(row);
		const edited = {
			...original,
			...(row || {})
		};

		const newLocationId = edited?.location_id;
		const validation = this.lotsTableLocationEditValidation(edited, newLocationId);

		if (!validation.ok) {
			showAlert(validation.message, "warning");
			return null;
		}

		await storeValue("lots_table_move_lot_id", original.nocopk);
		await storeValue("lots_table_move_location_id", newLocationId);

		try {
			const res = await qLotsTableMoveLocation.run();
			const movedCount = res?.[0]?.moved_count ?? 0;

			showAlert(`Moved ${movedCount} lot(s).`, "success");

			await qLots.run();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			await storeValue("lots_error", e?.message || String(e));
			return null;
		}
	},

