	async init() {
    txtErrLots.setText("");

    try {
      const requestedLot = String(
        appsmith.URL?.queryParams?.lot || ""
      ).trim();
      const validRequestedLot = !requestedLot || /^(LOT)-[A-Za-z0-9-]+$/i.test(requestedLot);

      const previousSelection = String(
        inpStrains.selectedOptionValue || "All"
      );
      const speciesRows = await qSpecies.run();
      const validSelections = new Set([
        "All",
        ...(speciesRows || [])
          .map(row => String(row?.species_strain || "").trim())
          .filter(Boolean)
      ]);

      if (!validSelections.has(previousSelection)) {
        await inpStrains.setSelectedOption("All");
      }

      await LotsPage.refresh();

      if (requestedLot) {
        if (!validRequestedLot) {
          txtErrLots.setText(`Invalid Lot deep link: ${requestedLot}`);
          return;
        }

        const rows = qLots.data || [];
        const requestedIndex = rows.findIndex(row =>
          String(row?.lot_id || "").trim().toLowerCase() === requestedLot.toLowerCase()
        );

        if (requestedIndex < 0) {
          txtErrLots.setText(`Lot not found on Lots page: ${requestedLot}`);
          return;
        }

        // qLots places a deep-linked Lot first even when the current filters
        // would normally hide it. Reset the table, then explicitly replace
        // its multi-row selection with only the deep-linked Lot.
        await resetWidget("tblLots", true);
        await tblLots.setSelectedRowIndices([requestedIndex]);

        if (String(appsmith.URL?.queryParams?.source || "").toLowerCase() === "qr") {
          showAlert(`Loaded ${rows[requestedIndex].lot_id} from QR scan.`, "success");
        }
      }
    } catch (e) {
      txtErrLots.setText(e?.message || String(e));
    }
  },

