	packageLotWeightG(row) {
		const value = Number(row?.packageable_weight_g);
		return Number.isFinite(value) && value > 0 ? +value.toFixed(2) : NaN;
	},

	selectedPackageRows() {
		return LotsPage.selectedLotRows().map(row => ({
			row,
			weightG: LotsPage.packageLotWeightG(row)
		}));
	},

	selectedPackageWeightG() {
		const rows = LotsPage.selectedPackageRows();
		return rows.length === 1 && Number.isFinite(rows[0].weightG)
			? rows[0].weightG
			: "";
	},

	packageSelectionValidation() {
		const base = LotsPage.lotModalValidation("package");
		if (!base.ok) return { ...base, rows: [] };

		const rows = LotsPage.selectedPackageRows();
		const invalid = rows.find(entry => !Number.isFinite(entry.weightG) || entry.weightG <= 0);
		if (invalid) {
			const lot = invalid.row?.lot_id || invalid.row?.nocopk || "Selected lot";
			return {
				ok: false,
				rows,
				message: `${lot} does not have a packageable weight. Set lot unit_size or an item default unit size.`
			};
		}

		return { ok: true, message: "", rows };
	},

	packageSelectedLotsSummary() {
		const validation = LotsPage.packageSelectionValidation();
		if (!validation.rows?.length) return "No lots selected.";

		return validation.rows.map((entry, index) => {
			const row = entry.row || {};
			const lot = row.lot_id || row.nocopk || `Lot ${index + 1}`;
			const item = row.item_name_mat || row.item_name || row.item_category_mat || "Unknown item";
			const strain = row.strain_species_strain_mat || "";
			const category = String(row.item_category_mat || "").toLowerCase();
			const unitSize = Number(row.unit_size);
			const poundBased = ["grain", "substrate", "casing", "fruiting_block", "all_in_one_bag"].includes(category);
			const poundText = poundBased && Number.isFinite(unitSize) && unitSize > 0
				? `${unitSize.toFixed(2).replace(/\.?0+$/, "")} lb / `
				: "";
			const strainText = strain ? ` — ${strain}` : "";
			return `${index + 1}. ${lot} — ${item} — ${poundText}${entry.weightG.toFixed(2)} g${strainText}`;
		}).join("\n");
	},

	defaultPackageCount() {
		return "1";
	},

	defaultPackageSizeG() {
		const weight = LotsPage.selectedPackageWeightG();
		return weight ? String(weight) : "";
	},

	requestedPackageWeightG() {
		const count = Number(inpPackageCount.text);
		const sizeG = Number(inpPackageSizeG.text);

		if (!Number.isFinite(count) || !Number.isFinite(sizeG)) {
			return NaN;
		}

		return count * sizeG;
	},

	hasEnoughPackageWeight() {
		const requested = LotsPage.requestedPackageWeightG();
		const available = LotsPage.selectedPackageWeightG();

		return Number.isFinite(requested)
			&& requested > 0
			&& available > 0
			&& requested <= available;
	},

	packageStorageLocationOptions() {
		const invalidNameParts = [
			"dark room",
			"fruiting",
			"freeze",
			"freezer",
			"fridge",
			"refrigerat",
			"cold shock",
			"lab",
			"shipped",
			"consumed",
			"compost",
			"expired"
		];

		const preferredNameParts = [
			"products storage",
			"product storage",
			"finished",
			"retail",
			"customer",
			"market"
		];

		return (qProductLocations.data || [])
			.filter(l => {
				const name = String(l.name || "").trim();
				const lower = name.toLowerCase();

				if (!name) return false;
				if (l.active === false) return false;

				if (invalidNameParts.some(part => lower.includes(part))) {
					return false;
				}

				return preferredNameParts.some(part => lower.includes(part));
			})
			.map(l => ({
				label: l.name,
				value: l.nocopk
			}));
	},

	defaultPackageStorageLocationId() {
		const opts = this.packageStorageLocationOptions();

		const productsStorage = opts.find(o =>
			String(o.label || "").trim().toLowerCase() === "products storage"
		);

		return (productsStorage || opts[0])?.value || "";
	},

	canSubmitPackage() {
		if (LotsPage.isPackageSubmitting()) return false;

		const validation = LotsPage.packageSelectionValidation();
		const count = Number(inpPackageCount.text);
		const selectedLocationId = inpPackageStorageLocation.selectedOptionValue;
		const validLocationIds = LotsPage.packageStorageLocationOptions().map(o => String(o.value));

		return validation.ok
			&& validation.rows.length > 0
			&& Number.isFinite(count)
			&& count === 1
			&& !!selectedLocationId
			&& validLocationIds.includes(String(selectedLocationId));
	},

