export default {
  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();
    if (email) return email;
    if (name) return name;
    return "system";
  },

  sql: {
    str(v) {
      if (v === undefined || v === null || v === "") return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
    arrBigint(arr) {
      if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
      const vals = arr.map(x => {
        const n = Number(x);
        return Number.isFinite(n) ? String(n) : "NULL";
      }).filter(x => x !== "NULL");
      if (vals.length === 0) return "ARRAY[]::bigint[]";
      return "ARRAY[" + vals.join(", ") + "]::bigint[]";
    }
  },

  async init() {
    try {
      const requestedProduct = String(
        appsmith.URL?.queryParams?.product || ""
      ).trim();
      const validRequestedProduct = !requestedProduct || /^(PROD)-[A-Za-z0-9-]+$/i.test(requestedProduct);

      await ProductsPage.refresh();

      if (requestedProduct) {
        if (!validRequestedProduct) {
          showAlert(`Invalid Product deep link: ${requestedProduct}`, "warning");
          return;
        }

        const rows = qProducts.data || [];
        const requestedIndex = rows.findIndex(row =>
          String(row?.product_id || "").trim().toLowerCase() === requestedProduct.toLowerCase()
        );

        if (requestedIndex < 0) {
          showAlert(`Product not found on Products page: ${requestedProduct}`, "warning");
          return;
        }

        await resetWidget("tblProducts", true);
        await tblProducts.setSelectedRowIndices([requestedIndex]);

        if (String(appsmith.URL?.queryParams?.source || "").toLowerCase() === "qr") {
          showAlert(`Loaded ${rows[requestedIndex].product_id} from QR scan.`, "success");
        }
      }
    } catch (e) {
      showAlert(e?.message || String(e), "error");
    }
  },

  selectedProductIds() {
    return (tblProducts.selectedRows || [])
      .map(r => Number(r.nocopk))
      .filter(Number.isFinite);
  },

  selectedTrayProducts() {
    return (tblProducts.selectedRows || []).filter(r =>
      ["fresh_tray", "freezer_tray"].includes(String(r.item_category_mat || ""))
    );
  },

  selectedFreezerTrayProducts() {
    return (tblProducts.selectedRows || []).filter(r =>
      String(r.item_category_mat || "") === "freezer_tray"
    );
  },

  selectedProductsSummary() {
    const rows = tblProducts.selectedRows || [];
    if (!rows.length) return "No products selected.";

    return rows.map(r =>
      `${r.product_id || r.nocopk} — ${r.name || r.item_category_mat || "Product"} — ${r.storage_location || "No location"}`
    ).join("\n");
  },

	isActiveProduct(row) {
		const trayStates = String(row?.tray_state || "")
			.toLowerCase()
			.split(/[,;|]+/)
			.map(s => s.trim())
			.filter(Boolean);

		const location = String(row?.storage_location || "")
			.toLowerCase()
			.replace(/[^a-z0-9]/g, "");

		const inactiveStates = [
			"empty_tray",
			"empty tray",
			"compost",
			"composted",
			"spoiled",
			"retired",
			"expired",
			"consumed",
			"shipped"
		];

		const inactiveLocations = [
			"compost",
			"consumed",
			"expired",
			"retired",
			"shipped"
		];

		return !trayStates.some(s => inactiveStates.includes(s))
			&& !inactiveLocations.includes(location);
	},

	isActiveTrayProduct(row) {
		return ProductsPage.isActiveProduct(row);
	},

	async refresh() {
		await Promise.allSettled([
			qProductLocationOptions.run(),
			qProductStrainOptions.run(),
			qFreezeDriedPackageItems.run()
		]);
		await resetWidget("tblProducts", true);
		await qProducts.run();
	},

  async showFreshTrays() {
    await selProductsCategory.setSelectedOption("fresh_tray");
    await ProductsPage.refresh();
  },

  async showFreezerTrays() {
    await selProductsCategory.setSelectedOption("freezer_tray");
    await ProductsPage.refresh();
  },

  productReadyLocationOptions() {
    const invalidNameParts = [
      "dark room",
      "fruiting",
      "freeze",
      "freezer",
      "fridge",
      "refrigerat",
      "cold shock",
      "lab",
      "shipped",
      "consumed",
      "compost",
      "expired",
      "retired"
    ];

    const preferredNameParts = [
      "products storage",
      "product storage",
      "fulfillment",
      "shipping",
      "retail",
      "market",
      "customer"
    ];

    return (qProductLocationOptions.data || [])
      .filter(l => {
        const name = String(l.name || "").trim();
        const lower = name.toLowerCase();

        if (!name) return false;
        if (l.active === false) return false;
        if (invalidNameParts.some(part => lower.includes(part))) return false;

        return preferredNameParts.some(part => lower.includes(part));
      })
      .map(l => ({
        label: l.name,
        value: l.nocopk
      }));
  },

  defaultProductReadyLocationId() {
    const opts = this.productReadyLocationOptions();

    const productsStorage = opts.find(o =>
      String(o.label || "").trim().toLowerCase() === "products storage"
    );

    return (productsStorage || opts[0])?.value || "";
  },

	isMoveFreezeDryerSubmitting() {
		return appsmith.store.products_move_freeze_dryer_submitting === true;
	},

	isRetireTraySubmitting() {
		return appsmith.store.products_retire_tray_submitting === true;
	},

	isPackageFreezeDriedSubmitting() {
		return appsmith.store.products_package_fd_submitting === true;
	},	

  freezeDryerLocationOptions() {
    return (qProductLocationOptions.data || [])
      .filter(l => {
        const name = String(l.name || "").toLowerCase();
        return l.active !== false && name.includes("freeze dryer");
      })
      .map(l => ({
        label: l.name,
        value: l.nocopk
      }));
  },

  defaultFreezeDryerLocationId() {
    const opts = this.freezeDryerLocationOptions();
    return opts[0]?.value || "";
  },

  canMoveFreezeDryer() {
    const rows = tblProducts.selectedRows || [];
    return rows.length > 0 && rows.every(r =>
      String(r.item_category_mat || "") === "freezer_tray" &&
      this.isActiveTrayProduct(r)
    );
  },

  canRetireTray() {
    const rows = tblProducts.selectedRows || [];
    return rows.length > 0 && rows.every(r =>
      ["fresh_tray", "freezer_tray"].includes(String(r.item_category_mat || "")) &&
      this.isActiveTrayProduct(r)
    );
  },

	canPackageFreezeDried() {
		const rows = tblProducts.selectedRows || [];

		return rows.length > 0
			&& rows.every(r => String(r.item_category_mat || "") === "freezer_tray")
			&& rows.every(r => ProductsPage.isActiveTrayProduct(r));
	},

	canSubmitMoveFreezeDryer() {
		if (ProductsPage.isMoveFreezeDryerSubmitting()) {
			return false;
		}

		const selectedLocationId = selFreezeDryerLocation.selectedOptionValue;
		const validLocationIds = ProductsPage.freezeDryerLocationOptions()
			.map(o => String(o.value));

		return ProductsPage.canMoveFreezeDryer()
			&& !!selectedLocationId
			&& validLocationIds.includes(String(selectedLocationId));
	},

	canSubmitRetireTray() {
		if (ProductsPage.isRetireTraySubmitting()) {
			return false;
		}

		return ProductsPage.canRetireTray()
			&& !!selRetireTrayReason.selectedOptionValue;
	},

	freezeDriedPackageItemOptions() {
	  return (qFreezeDriedPackageItems.data || [])
	    .filter(i => i && i.option_value && i.package_item_id)
	    .map(i => ({
	      label: i.label || `${i.name || i.item_id || i.package_item_id} — ${i.package_class}`,
	      value: i.option_value,
	      package_item_id: i.package_item_id,
	      item_id: i.item_id,
	      package_class: i.package_class
	    }));
	},

	defaultFreezeDriedPackageItemId() {
	  const opts = ProductsPage.freezeDriedPackageItemOptions();
	  const preferred = opts.find(o => o.item_id === "MUSH-DRIED" && o.package_class === "Retail")
	    || opts.find(o => o.package_class === "Retail")
	    || opts[0];
	  return preferred?.value || "";
	},

	selectedFreezeDriedPackageItem() {
	  const selected = String(selPkgFDPackageItem.selectedOptionValue || "");
	  return ProductsPage.freezeDriedPackageItemOptions()
	    .find(i => String(i.value || "") === selected) || null;
	},

	freezeDriedPackageRequest() {
	  const selectedPackageItem = ProductsPage.selectedFreezeDriedPackageItem();
	  return {
	    source_product_ids: ProductsPage.selectedProductIds(),
	    package_item_id: selectedPackageItem?.package_item_id ?? null,
	    package_size_g: ProductsPage.freezeDriedPackageItemSizeG(),
	    package_count: Number(inpPkgFDCount.text),
	    storage_location_id: selPkgFDLocation.selectedOptionValue || null,
	    use_by: dpPkgFDUseBy.formattedDate || null,
	    operator: ProductsPage.currentOperator(),
	    notes: String(inpPkgFDNotes.text || ""),
	    package_class: selectedPackageItem?.package_class || null
	  };
	},

	canSubmitPackageFreezeDried() {
	  if (ProductsPage.isPackageFreezeDriedSubmitting()) {
	    return false;
	  }
	  const count = Number(inpPkgFDCount.text);
	  const sizeG = ProductsPage.freezeDriedPackageItemSizeG();
	  const rows = tblProducts.selectedRows || [];
	  const selectedPackageItem = ProductsPage.selectedFreezeDriedPackageItem();
	  const selectedOptionValue = String(selPkgFDPackageItem.selectedOptionValue || "");
	  const validOptionValues = ProductsPage.freezeDriedPackageItemOptions().map(o => String(o.value));
	  const selectedLocationId = selPkgFDLocation.selectedOptionValue;
	  const validLocationIds = ProductsPage.productReadyLocationOptions().map(o => String(o.value));
	  const selectedWeightG = rows.reduce((sum, r) => sum + Number(r.net_weight_g || 0), 0);
	  const requiredWeightG = count * Number(sizeG || 0);

	  return ProductsPage.canPackageFreezeDried()
	    && Number.isInteger(count)
	    && count > 0
	    && !!sizeG
	    && !!dpPkgFDUseBy.formattedDate
	    && selectedWeightG >= requiredWeightG
	    && !!selectedPackageItem
	    && ["Retail", "Sample"].includes(selectedPackageItem.package_class)
	    && validOptionValues.includes(selectedOptionValue)
	    && !!selectedLocationId
	    && validLocationIds.includes(String(selectedLocationId));
	},

	async openMoveFreezeDryerModal() {
		if (!ProductsPage.canMoveFreezeDryer()) {
			showAlert("Select one or more active freezer tray products.", "warning");
			return;
		}

		await storeValue("products_move_freeze_dryer_submitting", false);

		inpMoveFreezeDryerNotes.setValue("");

		const defaultLocationId = ProductsPage.defaultFreezeDryerLocationId();

		if (defaultLocationId) {
			await selFreezeDryerLocation.setSelectedOption(defaultLocationId);
		} else {
			await selFreezeDryerLocation.setSelectedOption("");
			showAlert("No active Freeze Dryer location was found.", "warning");
		}

		await showModal(modalMoveFreezeDryer.name);
	},

	async onFreezeDriedPackageItemChanged() {
	  if (!ProductsPage.freezeDriedPackageItemSizeG()) {
	    await selPkgFDSizeG.setSelectedOption("5");
	  }
	},

	freezeDriedPackageItemSizeG(value = selPkgFDSizeG.selectedOptionValue) {
	  const sizeG = Number(value);
	  if (!Number.isFinite(sizeG) || sizeG <= 0) return null;
	  if (Math.abs(sizeG - 1) <= 0.01) return 1;
	  if (Math.abs(sizeG - 5) <= 0.01) return 5;
	  if (Math.abs(sizeG - 10) <= 0.01) return 10;
	  if (Math.abs(sizeG - 28.349523125) <= 0.02) return 28.349523125;
	  return null;
	},

