export default {
	sql: {
		str(v) {
			if (v === undefined || v === null || v === "") return "NULL";
			return "'" + String(v).replace(/'/g, "''") + "'";
		},
		num(v) {
			const n = Number(v);
			return Number.isFinite(n) ? String(n) : "NULL";
		},
		arrBigint(arr) {
			if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
			const vals = arr.map(x => {
				const n = Number(x);
				return Number.isFinite(n) ? String(n) : "NULL";
			}).filter(x => x !== "NULL");
			if (vals.length === 0) return "ARRAY[]::bigint[]";
			return "ARRAY[" + vals.join(", ") + "]::bigint[]";
		}
	},

	currentOperator() {
		const email = (appsmith.user?.email || "").trim().toLowerCase();
		const name = (appsmith.user?.name || "").trim();
		if (email) return email;
		if (name) return name;
		return "system";
	},

	selectedLotRows() {
		const storedId = Number(appsmith.store.harvest_selected_lot_id);
		if (Number.isFinite(storedId)) {
			const storedRow = (qLots.data || []).find(r => Number(r?.nocopk) === storedId);
			if (storedRow) return [storedRow];
		}

		const selectedRow = tblLots.selectedRow;
		if (selectedRow && selectedRow.nocopk != null) return [selectedRow];

		return (tblLots.selectedRows || [])
			.filter(r => r && r.nocopk != null)
			.slice(0, 1);
	},

	selectedLotIds() {
		return LotsHarvest.selectedLotRows().map(r => r.nocopk).filter(Boolean);
	},

	formatSelectedLots() {
		const rows = LotsHarvest.selectedLotRows();
		if (!rows.length) return "(No lots selected)";
		return rows.map(r => {
			const lotId = r.lot_id ?? r.nocopk;
			const inoc = r.inoculated_at ? moment(r.inoculated_at).format("YYYY-MM-DD") : "";
			const item = r.item_name_mat || "";
			const strain = r.strain_species_strain_mat || "";
			return `${lotId} | inoc:${inoc} | ${item} | ${strain}`.trim();
		}).join("\n");
	},

	lotIsRetired(row) {
		const status = String(row?.status || "").toLowerCase();
		return ["consumed", "expired", "retired", "compost", "composted", "compose"].some(s => status.includes(s));
	},

	lotModalValidation(actionOrOptions = {}) {
		const rows = LotsHarvest.selectedLotRows();
		const action = typeof actionOrOptions === "string" ? actionOrOptions : null;
		const options = typeof actionOrOptions === "object" && actionOrOptions !== null ? actionOrOptions : {};

		const rulesByAction = {
			inoculate: {
				requireAny: true,
				allowedCategories: ["grain", "lc_flask", "plate", "cordyceps_substrate", "all_in_one_bag"],
				requireNoStrain: true,
				requireNotInoculated: true,
				message: "Select one or more active grain, LC flask, plate, cordyceps substrate, or all-in-one bag lots that have not already been inoculated or assigned a strain."
			},
			draw_syringes: {
				requireSingle: true,
				allowedCategories: ["lc_flask"],
				message: "Select exactly one active LC flask lot to draw syringes."
			},
			harvest: {
				requireSingle: true,
				allowedCategories: ["fruiting_block", "cordyceps_substrate", "all_in_one_bag"],
				message: "Select exactly one active fruiting block, cordyceps substrate, or all-in-one bag lot to harvest."
			}
		};

		const rules = {
			...(action ? (rulesByAction[action] || {}) : {}),
			...options
		};

		if (rules.requireSingle && rows.length !== 1) {
			return { ok: false, message: rules.message || "Select exactly one valid lot." };
		}

		if ((rules.requireAny || !rules.requireSingle) && rows.length === 0) {
			return { ok: false, message: rules.message || "Select one or more valid lots." };
		}

		for (const row of rows) {
			const label = row.lot_id || row.nocopk || "Selected lot";
			const category = String(row.item_category_mat || "");

			if (rules.allowedCategories && !rules.allowedCategories.includes(category)) {
				return { ok: false, message: `${label} has category ${category || "(blank)"}; expected ${rules.allowedCategories.join(", ")}.` };
			}

			if (!rules.allowRetired && LotsHarvest.lotIsRetired(row)) {
				return { ok: false, message: `${label} is retired or unavailable (${row.status || "unknown status"}).` };
			}

			if (rules.requireNoStrain && row.strain_species_strain_mat) {
				return { ok: false, message: `${label} already has a strain (${row.strain_species_strain_mat}).` };
			}

			if (rules.requireNotInoculated && row.inoculated_at) {
				return { ok: false, message: `${label} was already inoculated (${row.inoculated_at}).` };
			}
		}

		return { ok: true, message: "" };
	},

	canOpenLotModal(actionOrOptions = {}) {
		return LotsHarvest.lotModalValidation(actionOrOptions).ok;
	},

	validateAndWarnLotModal(actionOrOptions = {}, fallbackMessage = "Invalid lot selection for this action.") {
		const result = LotsHarvest.lotModalValidation(actionOrOptions);
		if (!result.ok) {
			showAlert(result.message || fallbackMessage, "warning");
			return false;
		}
		return true;
	},
	async refresh() {
	  await qLots.run();
	  await resetWidget("tblLots", false);
	  await storeValue("harvest_selected_lot_id", null);
	  await storeValue("harvest_flush_no", "");
	  await storeValue("harvest_submitting", false);
	  await resetWidget("inpHarvestFlushNo", false);
	  await inpHarvestWeightG.setValue("");
	  await inpHarvestFreshTrayCount.setValue("0");
	  await inpHarvestFrozenTrayCount.setValue("1");
	  await inpHarvestNotes.setValue("");
	  await LotsHarvest.onHarvestCountsChanged();
	},

	canSubmitHarvest() {
	  const selectedRow = LotsHarvest.selectedLotRows()[0];
	  const selectedLotId = Number(selectedRow?.nocopk);
	  const weightG = Number(inpHarvestWeightG.text);

	  const flushText = inpHarvestFlushNo.text;
	  const flushNo = Number(
	    flushText !== undefined && flushText !== null && String(flushText).trim() !== ""
	      ? flushText
	      : (qHarvestFlushNo.data?.[0]?.next_flush_no ?? 1)
	  );

	  const freshTrayCount = LotsHarvest.harvestFreshTrayCount();
	  const frozenTrayCount = LotsHarvest.harvestFrozenTrayCount();

	  const freshLocationId = selHarvestFreshStorageLocation.selectedOptionValue
	    || LotsHarvest.defaultFreshHarvestLocationId();
	  const frozenLocationId = selHarvestFrozeStorageLocation.selectedOptionValue
	    || LotsHarvest.defaultFrozenHarvestLocationId();

	  return appsmith.store.harvest_submitting !== true
	    && Number.isFinite(selectedLotId)
	    && Number.isFinite(weightG)
	    && weightG > 0
	    && Number.isFinite(flushNo)
	    && flushNo > 0
	    && freshTrayCount + frozenTrayCount > 0
	    && (freshTrayCount <= 0 || !!freshLocationId)
	    && (frozenTrayCount <= 0 || !!frozenLocationId);
	},


	async verifyHarvestableLot() {
		return LotsHarvest.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.");
	},

	selectedHarvestItem() {
		return null;
	},

	selectedHarvestCategory() {
		const freshCount = LotsHarvest.harvestFreshTrayCount();
		const frozenCount = LotsHarvest.harvestFrozenTrayCount();

		if (freshCount > 0 && frozenCount > 0) return "mixed_trays";
		if (freshCount > 0) return "fresh_tray";
		if (frozenCount > 0) return "freezer_tray";

		return null;
	},

	freshHarvestLocationOptions() {
		const invalidNameParts = [
			"shipped",
			"shipping",
			"expired",
			"compost",
			"consumed",
			"retired",
			"freeze",
			"freezer",
			"lab",
			"dark room"
		];

		return (qProductLocations.data || [])
			.filter(l => {
				const name = String(l.name || "").trim();
				const lower = name.toLowerCase();

				if (!name) return false;
				if (l.active === false) return false;
				if (invalidNameParts.some(part => lower.includes(part))) return false;

				return lower.includes("fulfillment")
					|| lower.includes("product-ready")
					|| lower.includes("product ready")
					|| lower.includes("products storage")
					|| lower.includes("product storage");
			})
			.map(l => ({
				label: l.name,
				value: l.nocopk
			}));
	},

	defaultFreshHarvestLocationId() {
		const opts = LotsHarvest.freshHarvestLocationOptions();

		const fulfillment = opts.find(o =>
			String(o.label || "").trim().toLowerCase() === "fulfillment"
		);

		return (fulfillment || opts[0])?.value || "";
	},	

	defaultFrozenHarvestLocationId() {
		const opts = LotsHarvest.frozenHarvestLocationOptions();

		const freezer = opts.find(o => {
			const label = String(o.label || "").trim().toLowerCase();
			return label === "freezer" || label.includes("freezer");
		});

		return (freezer || opts[0])?.value || "";
	},	

	frozenHarvestLocationOptions() {
		const invalidNameParts = [
			"shipped",
			"shipping",
			"expired",
			"compost",
			"consumed",
			"retired",
			"fulfillment",
			"products storage",
			"product storage",
			"product-ready",
			"product ready",
			"lab",
			"dark room"
		];

		return (qProductLocations.data || [])
			.filter(l => {
				const name = String(l.name || "").trim();
				const lower = name.toLowerCase();

				if (!name) return false;
				if (l.active === false) return false;
				if (invalidNameParts.some(part => lower.includes(part))) return false;

				return lower.includes("freezer")
					|| lower.includes("frozen")
					|| lower.includes("freeze");
			})
			.map(l => ({
				label: l.name,
				value: l.nocopk
			}));
	},

	async onHarvestCountsChanged() {
		if (LotsHarvest.harvestFreshTrayCount() > 0) {
			const freshDefault = LotsHarvest.defaultFreshHarvestLocationId();
			await selHarvestFreshStorageLocation.setSelectedOption(freshDefault || "");
		} else {
			await selHarvestFreshStorageLocation.setSelectedOption("");
		}

		if (LotsHarvest.harvestFrozenTrayCount() > 0) {
			const frozenDefault = LotsHarvest.defaultFrozenHarvestLocationId();
			await selHarvestFrozeStorageLocation.setSelectedOption(frozenDefault || "");
		} else {
			await selHarvestFrozeStorageLocation.setSelectedOption("");
		}
	},
	async openHarvestModal(row) {
	  const selectedRow = row && row.nocopk != null
	    ? row
	    : (tblLots.selectedRow && tblLots.selectedRow.nocopk != null
	      ? tblLots.selectedRow
	      : (qLots.data || [])[0]);
	  if (!selectedRow || selectedRow.nocopk == null) {
	    showAlert("Select exactly one active fruiting block, cordyceps substrate, or all-in-one bag lot to harvest.", "warning");
	    return;
	  }

	  const selectedLotId = Number(selectedRow.nocopk);
	  await storeValue("harvest_selected_lot_id", selectedLotId);
	  await storeValue("harvest_flush_no", "");
	  await resetWidget("inpHarvestFlushNo", false);

	  if (!LotsHarvest.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.")) return;

	  await storeValue("harvest_submitting", false);

	  await inpHarvestWeightG.setValue("");
	  await inpHarvestFreshTrayCount.setValue("0");
	  await inpHarvestFrozenTrayCount.setValue("1");
	  await inpHarvestNotes.setValue("");

	  await Promise.allSettled([
	    qHarvestItems.run(),
	    qProductLocations.run()
	  ]);

	  const flushRows = await qHarvestFlushNo.run({ lotId: selectedLotId });
	  const rawNextFlush = Number(flushRows?.[0]?.next_flush_no ?? 1);
	  const nextFlush = Number.isFinite(rawNextFlush) && rawNextFlush > 0 ? rawNextFlush : 1;

	  await storeValue("harvest_flush_no", String(nextFlush));
	  await resetWidget("inpHarvestFlushNo", false);
	  await inpHarvestFlushNo.setValue(String(nextFlush));
	  await LotsHarvest.onHarvestCountsChanged();
	},

	harvestFreshTrayCount() {
	  const raw = inpHarvestFreshTrayCount.text;
	  const count = Number(
	    raw !== undefined && raw !== null && String(raw).trim() !== ""
	      ? raw
	      : 0
	  );
	  return Number.isFinite(count) && count > 0 ? count : 0;
	},


	harvestFrozenTrayCount() {
	  const raw = inpHarvestFrozenTrayCount.text;
	  const count = Number(
	    raw !== undefined && raw !== null && String(raw).trim() !== ""
	      ? raw
	      : 1
	  );
	  return Number.isFinite(count) && count > 0 ? count : 0;
	},


	async harvestSelectedLot() {
		if (!LotsHarvest.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.")) return;

		const weightG = Number(inpHarvestWeightG.text);
		const flushText = inpHarvestFlushNo.text;
		const flushNo = Number(
			flushText !== undefined && flushText !== null && String(flushText).trim() !== ""
				? flushText
				: (qHarvestFlushNo.data?.[0]?.next_flush_no ?? 1)
		);
		const freshTrayCount = LotsHarvest.harvestFreshTrayCount();
		const frozenTrayCount = LotsHarvest.harvestFrozenTrayCount();
		const totalTrayCount = freshTrayCount + frozenTrayCount;

		const freshLocationId = selHarvestFreshStorageLocation.selectedOptionValue
			|| LotsHarvest.defaultFreshHarvestLocationId();
		const frozenLocationId = selHarvestFrozeStorageLocation.selectedOptionValue
			|| LotsHarvest.defaultFrozenHarvestLocationId();

		const validFreshLocationIds = LotsHarvest.freshHarvestLocationOptions()
			.map(o => String(o.value));

		const validFrozenLocationIds = LotsHarvest.frozenHarvestLocationOptions()
			.map(o => String(o.value));

		if (!Number.isFinite(weightG) || weightG <= 0) {
			showAlert("Enter harvest weight in grams.", "warning");
			return;
		}

		if (!Number.isFinite(flushNo) || flushNo <= 0) {
			showAlert("Enter a valid flush number.", "warning");
			return;
		}

		if (totalTrayCount <= 0) {
			showAlert("Enter at least one fresh or freezer tray.", "warning");
			return;
		}

		if (
			freshTrayCount > 0
			&& (!freshLocationId || !validFreshLocationIds.includes(String(freshLocationId)))
		) {
			showAlert("Select a Fulfillment or product-ready destination for fresh harvest trays.", "warning");
			return;
		}

		if (
			frozenTrayCount > 0
			&& (!frozenLocationId || !validFrozenLocationIds.includes(String(frozenLocationId)))
		) {
			showAlert("Select a freezer/frozen destination for freezer tray harvest output.", "warning");
			return;
		}

		if (appsmith.store.harvest_submitting === true) return null;
		await storeValue("harvest_submitting", true);

		try {
			const res = await qHarvestLot.run();
			showAlert("Harvest created " + res[0].created_count + " tray product(s).", "success");
			/* standalone page: modal close not needed */
			await LotsHarvest.refresh();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		} finally {
			await storeValue("harvest_submitting", false);
		}
	}
};

