export default {
  sql: {
    str(value) {
      if (
        value === undefined ||
        value === null ||
        String(value).trim() === ""
      ) {
        return "NULL";
      }

      return "'" + String(value).trim().replace(/'/g, "''") + "'";
    },

    bool(value) {
      return value ? "TRUE" : "FALSE";
    },

    arrBigint(values) {
      const ids = (Array.isArray(values) ? values : [])
        .map(Number)
        .filter(Number.isFinite)
        .map(Math.trunc);

      if (!ids.length) {
        return "ARRAY[]::bigint[]";
      }

      return `ARRAY[${[...new Set(ids)].join(",")}]::bigint[]`;
    }
  },

  currentOperator() {
    const email = String(appsmith.user?.email || "")
      .trim()
      .toLowerCase();
    const name = String(appsmith.user?.name || "").trim();
    return email || name || "system";
  },

  selectedRows() {
    return Array.isArray(tblPrintQueue.selectedRows)
      ? tblPrintQueue.selectedRows
      : [];
  },

  selectedIds() {
    return [...new Set(
      this.selectedRows()
        .map(row => Number(row.nocopk))
        .filter(Number.isFinite)
        .map(Math.trunc)
    )];
  },

  normalizedStatus(row) {
    return String(row?.print_status || "").trim().toLowerCase();
  },

  hasPrintingSelection() {
    return this.selectedRows().some(
      row => this.normalizedStatus(row) === "printing"
    );
  },

  canRequeueSelected() {
    const rows = PrintQueuePage.selectedRows();
    const reason = String(inpPQStatusReason.text || "").trim();
    if (!rows.length || PrintQueuePage.hasPrintingSelection() || !reason) {
      return false;
    }
    return rows.every(row => ["printed", "error"].includes(PrintQueuePage.normalizedStatus(row)));
  },

  canApplyStatus() {
    const rows = this.selectedRows();
    const newStatus = String(selPQNewStatus.selectedOptionValue || "").trim();

    if (!rows.length || this.hasPrintingSelection() || !newStatus) {
      return false;
    }

    if (
      newStatus === "Error" &&
      !String(inpPQStatusReason.text || "").trim()
    ) {
      return false;
    }

    return ["Printed", "Error"].includes(newStatus);
  },

  async refresh() {
    await Promise.allSettled([
      resetWidget("selPQNewStatus", true),
      resetWidget("inpPQStatusReason", true),
      resetWidget("tblPrintQueue", true)
    ]);
    return qPrintQueue.run();
  },

  async clearFilters() {
    await Promise.allSettled([
      resetWidget("selPQStatus", true),
      resetWidget("selPQTarget", true),
      resetWidget("selPQSourceKind", true),
      resetWidget("selPQLabelType", true),
      resetWidget("inpPQClaimedBy", true),
      resetWidget("chkPQErrorsOnly", true),
      resetWidget("inpPQSearch", true),
      resetWidget("dpPQCreatedFrom", true),
      resetWidget("dpPQCreatedTo", true)
    ]);

    return this.refresh();
  },

  async runStatusUpdate(newStatus, clearError) {
    const ids = PrintQueuePage.selectedIds();
    const reason = String(inpPQStatusReason.text || "").trim();
    if (!ids.length) {
      showAlert("Select at least one print job.", "warning");
      return null;
    }
    if (PrintQueuePage.hasPrintingSelection()) {
      showAlert("A job currently marked Printing cannot be changed or requeued.", "error");
      return null;
    }
    if (["Queued", "Error"].includes(String(newStatus || "")) && !reason) {
      showAlert(`Enter a reason before changing print jobs to ${newStatus}.`, "warning");
      return null;
    }

    const extractUpdatedCount = value => {
      if (Array.isArray(value)) {
        for (const entry of value) {
          const found = extractUpdatedCount(entry);
          if (Number.isFinite(found)) return found;
        }
        return null;
      }
      if (!value || typeof value !== "object") return null;

      const direct = Number(value.updated_count ?? value.mp_print_queue_set_status);
      if (Number.isFinite(direct)) return direct;

      for (const entry of Object.values(value)) {
        const found = extractUpdatedCount(entry);
        if (Number.isFinite(found)) return found;
      }
      return null;
    };

    try {
      const result = await qPQSetStatus.run({
        print_queue_ids: ids,
        new_status: newStatus,
        clear_error: clearError === true,
        reason,
        operator: PrintQueuePage.currentOperator()
      });

      const returnedCount = extractUpdatedCount(result) ?? extractUpdatedCount(qPQSetStatus.data);
      const updatedCount = Number.isFinite(returnedCount) && returnedCount > 0
        ? returnedCount
        : ids.length;

      showAlert(`${updatedCount} print job(s) changed to ${newStatus}.`, "success");
      await Promise.allSettled([
        resetWidget("selPQNewStatus", true),
        resetWidget("inpPQStatusReason", true),
        resetWidget("tblPrintQueue", true)
      ]);
      await qPrintQueue.run();
      return result;
    } catch (error) {
      showAlert(error?.message || String(error), "error");
      return null;
    }
  },

  async requeueSelected() {
    const reason = String(inpPQStatusReason.text || "").trim();
    if (!reason) {
      showAlert("Enter a reason before requeueing print jobs.", "warning");
      return null;
    }
    if (!PrintQueuePage.canRequeueSelected()) {
      showAlert("Select only Printed or Error jobs. Printing jobs cannot be requeued.", "warning");
      return null;
    }
    return PrintQueuePage.runStatusUpdate("Queued", chkPQClearError.isChecked);
  },

  async applySelectedStatus() {
    if (!this.canApplyStatus()) {
      showAlert(
        "Select one or more inactive jobs and choose Printed or Error. A reason is required for Error.",
        "warning"
      );
      return null;
    }

    return this.runStatusUpdate(
      selPQNewStatus.selectedOptionValue,
      selPQNewStatus.selectedOptionValue === "Printed"
    );
  }
};

