  recipePreviewMarkdown(showNotes = false) {
    const recipePk = Number(selRecipePreview.selectedOptionValue || 0);
    if (!recipePk) {
      return "# Recipe Preview\n\nSelect a Recipe above to display its complete database-defined recipe.";
    }

    const recipe = (qRecipeAdminRecipes.data || []).find(r => Number(r.nocopk) === recipePk);
    if (!recipe) {
      return "# Recipe Preview\n\nThe selected Recipe is no longer available. Refresh the Recipe list and select another Recipe.";
    }

    showNotes = showNotes === true;
    const ingredients = (qRecipeAdminPreviewIngredients.data || [])
      .filter(r => r.active === true)
      .slice()
      .sort((a, b) =>
        Number(a.sort_order ?? 999999) - Number(b.sort_order ?? 999999) ||
        String(a.ingredient_name || "").localeCompare(String(b.ingredient_name || "")) ||
        Number(a.nocopk || 0) - Number(b.nocopk || 0)
      );
    const steps = (qRecipeAdminPreviewSteps.data || [])
      .filter(r => r.active === true)
      .slice()
      .sort((a, b) =>
        Number(a.section_order ?? 999999) - Number(b.section_order ?? 999999) ||
        Number(a.step_order ?? 999999) - Number(b.step_order ?? 999999) ||
        Number(a.nocopk || 0) - Number(b.nocopk || 0)
      );

    const clean = value => String(value ?? "").trim();
    const oneLine = value => clean(value).replace(/\s+/g, " ");
    const formatNumber = value => {
      if (value === null || value === undefined || value === "") return "";
      const n = Number(value);
      if (!Number.isFinite(n)) return clean(value);
      return Number.isInteger(n) ? String(n) : String(Number(n.toFixed(6)));
    };
    const quantity = row => {
      const display = oneLine(row.quantity_text);
      if (display) return display;
      const amount = formatNumber(row.amount);
      const amountMax = formatNumber(row.amount_max);
      const unit = oneLine(row.unit);
      if (!amount) return unit;
      const range = amountMax ? `${amount}–${amountMax}` : amount;
      return unit ? `${range} ${unit}` : range;
    };
    const ingredientText = row => {
      const name = oneLine(row.ingredient_name || row.ingredient_id || "Ingredient");
      const qty = quantity(row);
      const vendor = oneLine(row.vendor_name);
      let text = qty ? `**${name}:** ${qty}` : `**${name}**`;
      if (vendor) text += ` _(source: ${vendor})_`;
      if (row.optional === true) text += " _(optional)_";
      return text;
    };

    const children = new Map();
    ingredients.forEach(row => {
      const parent = Number(row.parent_recipe_ingredient_nocopk || 0);
      if (!children.has(parent)) children.set(parent, []);
      children.get(parent).push(row);
    });

    const ingredientLines = [];
    const rendered = new Set();
    const renderRows = (rows, depth = 0) => {
      const indent = "    ".repeat(depth);
      const processed = new Set();

      rows.forEach(row => {
        const rowKey = String(row.nocopk);
        if (processed.has(rowKey) || rendered.has(rowKey)) return;

        const alt = oneLine(row.alternative_group);
        if (alt) {
          const alternatives = rows.filter(candidate => oneLine(candidate.alternative_group) === alt);
          if (alternatives.length > 1) {
            alternatives.forEach(candidate => {
              processed.add(String(candidate.nocopk));
              rendered.add(String(candidate.nocopk));
            });
            ingredientLines.push(`${indent}- **Choose one:**`);
            alternatives.forEach(candidate => {
              ingredientLines.push(`${indent}    - ${ingredientText(candidate)}`);
              if (showNotes && oneLine(candidate.notes)) {
                ingredientLines.push(`${indent}        - _Admin note: ${oneLine(candidate.notes)}_`);
              }
              const nested = children.get(Number(candidate.nocopk)) || [];
              if (nested.length) renderRows(nested, depth + 2);
            });
            return;
          }
        }

        processed.add(rowKey);
        rendered.add(rowKey);
        ingredientLines.push(`${indent}- ${ingredientText(row)}`);
        if (showNotes && oneLine(row.notes)) {
          ingredientLines.push(`${indent}    - _Admin note: ${oneLine(row.notes)}_`);
        }
        const nested = children.get(Number(row.nocopk)) || [];
        if (nested.length) renderRows(nested, depth + 1);
      });
    };

    renderRows(children.get(0) || []);

    const lines = [];
    lines.push(`# ${clean(recipe.name) || clean(recipe.recipe_id) || "Recipe"}`);
    if (clean(recipe.recipe_id)) lines.push("", `_${clean(recipe.recipe_id)}_`);
    if (recipe.active !== true) lines.push("", "> **Status:** Inactive");
    if (clean(recipe.batch_yield_text)) lines.push("", `**Batch yield / output:** ${clean(recipe.batch_yield_text)}`);
    if (clean(recipe.description)) lines.push("", clean(recipe.description));

    lines.push("", "## Ingredients", "");
    if (ingredientLines.length) {
      lines.push(...ingredientLines);
    } else if (clean(recipe.ingredients)) {
      const legacy = clean(recipe.ingredients).split(";").map(v => v.trim()).filter(Boolean);
      lines.push(...(legacy.length > 1 ? legacy.map(v => `- ${v}`) : [clean(recipe.ingredients)]));
    } else {
      lines.push("_No structured ingredients have been recorded for this Recipe._");
    }

    const sectionMap = new Map();
    steps.forEach(step => {
      const section = oneLine(step.section) || "Instructions";
      if (!sectionMap.has(section)) sectionMap.set(section, []);
      sectionMap.get(section).push(step);
    });

    if (steps.length) {
      sectionMap.forEach((sectionSteps, section) => {
        lines.push("", `## ${section}`, "");
        sectionSteps.forEach(step => {
          lines.push(`- ${clean(step.instruction)}`);
          if (showNotes && oneLine(step.notes)) lines.push(`    - _Admin note: ${oneLine(step.notes)}_`);
        });
      });
    } else {
      lines.push("", "## Instructions", "", "_No structured instructions have been recorded for this Recipe._");
    }

    if (showNotes && clean(recipe.notes)) {
      lines.push("", "## Administrative Notes", "", clean(recipe.notes));
    }

    return lines.join("\n");
  },


  recipePreviewHtml(showNotes = false) {
    const recipePk = Number(selRecipePreview.selectedOptionValue || 0);
    const recipe = (qRecipeAdminRecipes.data || []).find(r => Number(r.nocopk) === recipePk);
    if (!recipePk || !recipe) return "";

    const markdown = this.recipePreviewMarkdown(showNotes === true);
    const clean = value => String(value ?? "").trim();
    const escapeHtml = value => String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/\"/g, "&quot;")
      .replace(/'/g, "&#39;");
    const inline = value => escapeHtml(value)
      .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      .replace(/_(.+?)_/g, "<em>$1</em>");

    const content = [];
    markdown.split("\n").forEach(rawLine => {
      const line = String(rawLine || "");
      if (!line.trim()) return;

      if (line.startsWith("# ")) {
        content.push(`<h1>${inline(line.slice(2))}</h1>`);
        return;
      }
      if (line.startsWith("## ")) {
        const heading = line.slice(3);
        const adminClass = heading === "Administrative Notes" ? " admin-section" : "";
        content.push(`<h2 class="${adminClass.trim()}">${inline(heading)}</h2>`);
        return;
      }
      if (line.startsWith("> ")) {
        content.push(`<div class="status">${inline(line.slice(2))}</div>`);
        return;
      }

      const bullet = line.match(/^(\s*)-\s+(.*)$/);
      if (bullet) {
        const depth = Math.min(6, Math.floor(bullet[1].length / 4));
        const text = bullet[2];
        const adminClass = /_Admin note:/i.test(text) ? " admin-note" : "";
        content.push(
          `<div class="bullet${adminClass}" style="margin-left:${depth * 18}px">` +
          `<span class="bullet-mark">•</span><span>${inline(text)}</span></div>`
        );
        return;
      }

      const recipeIdClass = /^_.+_$/.test(line.trim()) ? " recipe-id" : "";
      content.push(`<p class="${recipeIdClass.trim()}">${inline(line)}</p>`);
    });

    const title = escapeHtml(clean(recipe.name) || clean(recipe.recipe_id) || "Recipe");
    return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title}</title>
<style>
  @page { size: Letter; margin: 0.65in 0.75in; }
  * { box-sizing: border-box; }
  html, body { background: #fff; color: #202124; }
  body {
    margin: 0;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10.5pt;
    line-height: 1.48;
  }
  .document {
    max-width: 7.1in;
    margin: 0 auto;
    padding: 0.55in 0.25in 0.7in;
  }
  h1 {
    margin: 0 0 0.12in;
    color: #111827;
    font-size: 24pt;
    line-height: 1.12;
    font-weight: 700;
  }
  h2 {
    margin: 0.30in 0 0.10in;
    padding-bottom: 0.04in;
    border-bottom: 1px solid #d1d5db;
    color: #1f2937;
    font-size: 14.5pt;
    line-height: 1.2;
    page-break-after: avoid;
    break-after: avoid;
  }
  p { margin: 0 0 0.10in; }
  p.recipe-id { margin-top: -0.02in; color: #6b7280; font-size: 9.5pt; }
  .status {
    margin: 0.10in 0;
    padding: 0.07in 0.10in;
    border-left: 3px solid #b45309;
    background: #fffbeb;
    color: #78350f;
  }
  .bullet {
    display: flex;
    gap: 0.08in;
    margin: 0 0 0.075in;
    page-break-inside: avoid;
    break-inside: avoid;
  }
  .bullet-mark { flex: 0 0 auto; font-weight: 700; }
  .admin-note {
    margin-top: -0.025in;
    padding: 0.045in 0.07in;
    border-left: 2px solid #c2410c;
    background: #fff7ed;
    color: #7c2d12;
    font-size: 9.5pt;
  }
  h2.admin-section { color: #9a3412; border-color: #fdba74; }
  strong { color: #111827; }
  em { color: #4b5563; }
  @media print {
    body { font-size: 10.5pt; }
    .document { max-width: none; margin: 0; padding: 0; }
    h1, h2, p, .bullet, .status { orphans: 3; widows: 3; }
  }
</style>
<script>
  window.addEventListener("load", function () {
    window.setTimeout(function () { window.print(); }, 150);
  });
</script>
</head>
<body>
<main class="document">
${content.join("\n")}
</main>
</body>
</html>`;
  },

  async printRecipePreview() {
    const recipePk = Number(selRecipePreview.selectedOptionValue || 0);
    const recipe = (qRecipeAdminRecipes.data || []).find(r => Number(r.nocopk) === recipePk);
    if (!recipePk || !recipe) {
      showAlert("Select a Recipe before printing.", "warning");
      return;
    }

    const html = this.recipePreviewHtml(chkRecipePreviewShowNotes.isChecked === true);
    if (!html) {
      showAlert("Unable to build the printable Recipe document.", "error");
      return;
    }

    const rawName = String(recipe.recipe_id || recipe.name || "recipe").trim();
    const safeName = rawName
      .replace(/[^A-Za-z0-9._-]+/g, "-")
      .replace(/^-+|-+$/g, "") || "recipe";
    const fileName = `${safeName}-recipe.html`;

    try {
      await download(html, fileName, "text/html");
      showAlert(`Printable Recipe downloaded as ${fileName}. Open it to print or save as PDF.`, "success");
    } catch (e) {
      showAlert(`Unable to produce printable Recipe: ${e?.message || String(e)}`, "error");
    }
  },
  async refreshLotComponents() {
    await qRecipeAdminLotComponents.run();
    showAlert("Lot component history refreshed.", "success");
  }
};

variables.value:
{
  str(v) {
    if (v === undefined || v === null || v === "") return "NULL";
    return "'" + String(v).replace(/'/g, "''") + "'";
  },
  num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? String(n) : "NULL";
  },
  bool(v) {
    return v === true ? "TRUE" : "FALSE";
  }
}
